async function main() {
  console.log(`About to send ${emails.length} emails.`);
  const results = [];
  for (const email of emails) {
    try {
      const payload = {
        from: "JB at WashFoldKit <jb@washfoldkit.com>",
        to: email.to,
        subject: email.subject,
        html: email.html,
        text: email.text,
      };
      const res = await resend.emails.send(payload);
      console.log(`Sent to ${email.to[0]}: ${JSON.stringify(res)}`);
      results.push({ to: email.to[0], status: "sent", id: res?.data?.id || null });
    } catch (err) {
      console.error(`FAILED for ${email.to[0]}:`, err);
      results.push({ to: email.to[0], status: "failed", error: String(err) });
    }
    // Small delay to be gentle on rate limits
    await new Promise(r => setTimeout(r, 600));
  }
  require('fs').writeFileSync('send_results.json', JSON.stringify(results, null, 2));
  console.log('Done. Results written to send_results.json');
}

main();
